// RT-08 (content rules), attack 28: the credits page marks nanostores "build and tests only", but its code
// reaches the reader: site/src/lib/highlight.ts (the highlight store of the shell, SPEC.md 7.6) and
// site/src/lib/state.ts import it, and the client chunk built from state.ts carries nanostores' runtime
// (`globalThis.nanostoresGlobal`). The page then says "4 of them reach the reader's browser". SPEC.md 7.9:
// "A credits page lists every third-party asset ... and the licences of bundled libraries".
// The table is generated by site/src/lib/pages/dependencies.ts (`dependencyRows`, `SHIPPED`).
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { dependencyRows } from '../../src/lib/pages/dependencies';

const src = (p: string) => readFileSync(fileURLToPath(new URL(`../../src/${p}`, import.meta.url)), 'utf8');

describe('credits page, packages shipped to the reader', () => {
  it('nanostores is imported by client code', () => {
    expect(src('lib/highlight.ts')).toMatch(/from 'nanostores'/);
    expect(src('lib/state.ts')).toMatch(/from 'nanostores'/);
  });
  // regression: P3-RT-08-10
  it('the credits row of nanostores says it reaches the reader', () => {
    const row = dependencyRows().find((r) => r.name === 'nanostores');
    expect(row, 'nanostores row').toBeDefined();
    // Observed at 69546f0: shipped null, rendered as "build and tests only".
    expect(row!.shipped, 'nanostores shipped column').not.toBeNull();
  });
});
